import numpy as np
atoms=[]
def add(el,p): atoms.append((el,np.array(p,float)))
def unit(v): v=np.array(v,float); return v/np.linalg.norm(v)
def rot(v,axis,deg):
    axis=unit(axis); t=np.radians(deg)
    return v*np.cos(t)+np.cross(axis,v)*np.sin(t)+axis*np.dot(axis,v)*(1-np.cos(t))

add('Ta',[0,0,0])
for p in [[0,2.55,0],[0,-2.55,0],[0,0,2.55],[0,0,-2.55]]: add('Br',p)

def methyl(N,dirv,nrm):
    C=N+1.46*dirv; add('C',C)
    # three H tetrahedral around C, away from N
    a=unit(dirv)
    for k in range(3):
        h=rot(nrm,a,120*k)
        add('H',C+1.09*unit(a*np.cos(np.radians(70.5))+h*np.sin(np.radians(70.5))))

def urea(sign):
    x=np.array([sign,0,0.]); nrm=unit([0,1,-1]) # plane normal
    O=2.10*x; add('O',O)
    # C: Ta-O-C ~ 145 deg
    dOC=rot(x,nrm,35); C=O+1.26*dOC; add('C',C)
    for s in (1,-1):
        dCN=rot(-dOC,nrm,s*60); N=C+1.36*dCN; add('N',N)
        for s2 in (1,-1):
            dNC=rot(-dCN,nrm,s2*60)
            methyl(N,dNC,nrm)
urea(1); urea(-1)
with open('init.xyz','w') as f:
    f.write(f"{len(atoms)}\n[TaBr4(OC(NMe2)2)2]+ initial\n")
    for el,p in atoms: f.write(f"{el} {p[0]:.4f} {p[1]:.4f} {p[2]:.4f}\n")
print(len(atoms))
